from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class VolumeConfirmedMove(Strategy):
    rationale = (
        "Volume-confirmed directional moves indicate strong momentum in a stock. "
        "By identifying such moves early, we can potentially capitalize on the continuation of that trend."
    )

    def __init__(self, window: int = 10) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window + 1)
        if history.is_empty():
            return Signal(information_available_at=stamp, weights={})

        latest_closes = view.closes()
        if latest_closes.height < self._window + 1:
            return Signal(information_available_at=stamp, weights={})

        picks: list[str] = []
        for symbol in view.symbols:
            if symbol not in history["symbol"].to_list():
                continue
            close_history = [float(v) for v in history.filter(pl.col("symbol") == symbol)["adj_close"].sort().to_list()]
            latest_close = float(latest_closes[symbol][0])
            volume_history = [int(v) for v in history.filter(pl.col("symbol") == symbol)["volume"].sort().to_list()]

            if len(close_history) < self._window + 1:
                continue

            # Check for a significant move
            latest_move = (latest_close - close_history[-2]) / close_history[-2]
            if latest_move > 0.05:  # Strong bullish move
                if volume_history[-1] >= 1.5 * sum(volume_history[-self._window : -1]):
                    picks.append(symbol)
            elif latest_move < -0.05:  # Strong bearish move
                if volume_history[-1] >= 1.5 * sum(volume_history[-self._window : -1]):
                    picks.append(symbol)

        if not picks:
            return Signal(information_available_at=stamp, weights={})
        weight = 1.0 / len(picks)
        return Signal(
            information_available_at=stamp,
            weights={s: weight for s in picks},
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
